from pathlib import Path
from decimal import Decimal
import csv,json,math
with Path('/tmp/exposed-funding-entry-counts-20261023.csv').open() as f: counts={int(r['parliament_member_id']):int(r['funding_entries']) for r in csv.DictReader(f)}
rows=json.loads(Path('/tmp/exposed-current-term-gbp-totals-20261023.json').read_text())
grid=[[0]*53 for _ in range(19)]
for r in rows:
 if r['amount'] is None:continue
 x=counts[r['member_id']]; a=Decimal(r['amount']); col=round(x/2.5); row=round((6.5-math.log10(float(a)))/.25);row=max(0,min(18,row));grid[row][col]+=1
labels={2:'£1m',6:'£100k',10:'£10k',14:'£1k',18:'£100'}
print('Declared GBP total, logarithmic scale')
for i,row in enumerate(grid): print(f'{labels.get(i,""):>6} │'+''.join(' ' if n==0 else '·' if n==1 else '●' if n<5 else '█' for n in row))
print('       └'+'─'*53)
print('        0         25        50        75        100       125')
print('                         Funding entries per MP')
