SELECT date_trunc('month',registration_date)::date AS month_start,count(*) AS declarations,count(DISTINCT member_id) AS members FROM exposed.declarations WHERE registration_date >= '2024-07-09T00:00:00Z' GROUP BY 1 ORDER BY declarations DESC,month_start LIMIT 5;
COMMIT;
"""
r=subprocess.run(['psql',os.environ['DATABASE_URL'],'-X','-v','ON_ERROR_STOP=1','-c',sql],capture_output=True,text=True)
